//! Compiles the native C shim that this tool links against.
//!
//! The `cc` crate locates a system C compiler through the usual `CC`/`AR`
//! environment variables (or a platform default such as `cc`/`clang`). It
//! emits the correct `cargo:rustc-link-*` directives for the target, so the
//! Rust side only has to declare the `extern "C"` signatures in `src/ffi.rs`.

fn main() {
    let include = "native";

    for source in ["native/sysinfo.c", "native/sysinfo.h"] {
        println!("cargo:rerun-if-changed={source}");
    }

    cc::Build::new()
        .file("native/sysinfo.c")
        .include(include)
        .flag_if_supported("-Wall")
        .flag_if_supported("-Wextra")
        .flag_if_supported("-Wconversion")
        .compile("systool_sysinfo");
}

#ifndef SYSTOOL_SYSINFO_H
#define SYSTOOL_SYSINFO_H

#include <stddef.h>

#ifdef __cplusplus
extern "C" {
#endif

/* Value of sysconf(_SC_PAGESIZE) in bytes, or -1 on failure. */
long systool_page_size(void);

/* Writes the uname(2) machine name into buf as a NUL-terminated string.
 * Returns the number of bytes written (excluding the NUL), or -1 if the
 * buffer is too small or uname fails. */
long systool_machine(char *buf, size_t len);

/* The calling process id. */
long systool_getpid(void);

#ifdef __cplusplus
}
#endif

#endif /* SYSTOOL_SYSINFO_H */

#define _POSIX_C_SOURCE 200809L

#include "sysinfo.h"

#include <string.h>
#include <sys/utsname.h>
#include <unistd.h>

long systool_page_size(void) {
    return (long)sysconf(_SC_PAGESIZE);
}

long systool_machine(char *buf, size_t len) {
    struct utsname info;
    size_t n;

    if (buf == NULL || len == 0) {
        return -1;
    }
    if (uname(&info) != 0) {
        return -1;
    }

    n = strlen(info.machine);
    if (n >= len) {
        return -1;
    }
    memcpy(buf, info.machine, n + 1);

    return (long)n;
}

long systool_getpid(void) {
    return (long)getpid();
}

//! Raw `extern "C"` declarations for the shim in `native/sysinfo.c`.
//!
//! `build.rs` compiles that file and links the resulting static library, so
//! no `#[link]` attribute is needed here. The `c_*` aliases from
//! `std::os::raw` are Rust's definitions of the matching C types and are
//! guaranteed to have the correct size and alignment on every target, which
//! is what makes it safe to pass them across the FFI boundary.

use std::os::raw::{c_char, c_long};

extern "C" {
    /// `sysconf(_SC_PAGESIZE)`, or `-1` on failure.
    pub fn systool_page_size() -> c_long;

    /// Copies `uname(2)`'s machine name into `buf` as a NUL-terminated
    /// string. Returns the number of bytes written (excluding the NUL), or
    /// `-1` if `buf` is too small or `uname` fails.
    pub fn systool_machine(buf: *mut c_char, len: usize) -> c_long;

    /// The calling process id.
    pub fn systool_getpid() -> c_long;
}

//! Safe, typed wrappers around the OS primitives used by this tool.
//!
//! Two styles of access are demonstrated:
//!
//! * calls into our own C shim through [`crate::ffi`], and
//! * direct libc calls using the C type aliases from the `libc` crate, whose
//!   size and signedness follow the platform ABI.

use std::ffi::CStr;
use std::io;

use crate::ffi;

/// Buffer size used when reading the machine name from `uname(2)`.
const MACHINE_CAP: usize = 256;

/// The calling process id, obtained through the C shim.
pub fn pid() -> libc::pid_t {
    // `getpid(2)` cannot fail, so the cast is always valid.
    unsafe { ffi::systool_getpid() as libc::pid_t }
}

/// The real user id, read straight from libc using OS-level C types.
pub fn uid() -> libc::uid_t {
    unsafe { libc::getuid() }
}

/// The system page size in bytes, obtained through the C shim.
pub fn page_size() -> io::Result<libc::c_long> {
    let value = unsafe { ffi::systool_page_size() };
    if value < 0 {
        Err(io::Error::last_os_error())
    } else {
        Ok(value)
    }
}

/// The machine hardware name reported by `uname(2)`, obtained through the C
/// shim.
pub fn machine() -> io::Result<String> {
    let mut buf = [0 as libc::c_char; MACHINE_CAP];
    let written = unsafe { ffi::systool_machine(buf.as_mut_ptr(), buf.len()) };

    if written < 0 {
        return Err(io::Error::last_os_error());
    }

    // The shim guarantees a NUL terminator within `buf`.
    let name = unsafe { CStr::from_ptr(buf.as_ptr()) };
    Ok(name.to_string_lossy().into_owned())
}

mod ffi;
mod sys;

use std::io;
use std::process::ExitCode;

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("systool: {err}");
            ExitCode::FAILURE
        }
    }
}

fn run() -> io::Result<()> {
    println!("pid          : {}", sys::pid());
    println!("uid          : {}", sys::uid());
    println!("page size    : {} bytes", sys::page_size()?);
    println!("architecture : {}", sys::machine()?);
    Ok(())
}

#!/bin/bash
ZIG=/tmp/opencode/zig-aarch64-linux-0.14.1/zig
argv=()
for a in "$@"; do
    case "$a" in
        -Wl,--fix-cortex-a53-843419)
            continue
            ;;
        --target=aarch64-unknown-linux-gnu) argv+=("--target=aarch64-linux-gnu") ;;
        --target=x86_64-unknown-linux-gnu)  argv+=("--target=x86_64-linux-gnu") ;;
        *) argv+=("$a") ;;
    esac
done
exec "$ZIG" cc "${argv[@]}"
